function areOccurrencesEqual(s) {
  const counts = new Array(26).fill(0);
  for (const ch of s) {
    counts[ch.charCodeAt(0) - 97]++;
  }
  let target = 0;
  for (const count of counts) {
    if (count === 0) {
      continue;
    }
    if (target === 0) {
      target = count;
    } else if (count !== target) {
      return false;
    }
  }
  return true;
}

