function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const kinds = size === 'large' ? 1 + pick(26) : 1 + pick(4);
  const each = size === 'large' ? Math.max(1, Math.floor(1000 / kinds) - pick(3)) : 1 + pick(3);
  const start = pick(26 - kinds + 1);
  let chars = [];
  for (let k = 0; k < kinds; k++) for (let c = 0; c < each; c++) chars.push(letters[start + k]);
  if (size === 'small' && rand() < 0.4) {
    chars = Array.from({ length: 1 + pick(8) }, () => letters[pick(3)]);
  } else if (rand() < 0.5) {
    const at = pick(chars.length);
    if (rand() < 0.5 && chars.length < 1000) chars.push(chars[at]);
    else chars[at] = letters[pick(26)];
  }
  for (let i = chars.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  return [chars.join('')];
}
